INSERT IGNORE INTO `products` (`id`, `name`, `slug`, `category`, `description`, `composition`, `care_instructions`, `instagram_url`, `measurements`, `price`, `sale_price`, `sale_starts_at`, `sale_ends_at`, `is_new_release`, `is_active`, `created_at`) VALUES (1,'Vestido Midi Alfaiataria Duás','vestido-midi-alfaiataria-duas','Vestidos','Vestido midi em alfaiataria nobre com decote estruturado e fenda lateral sutil. Peça desenhada por Larissa e Letícia com caimento impecável para ocasiões editoriais e cotidianas elegantes.','92% Poliéster Encorpado, 8% Elastano. Forro 100% Acetato.','Lavar à mão ou a seco profissionalmente. Não usar alvejante.',NULL,NULL,790.00,NULL,NULL,NULL,1,1,'2026-09-09 13:59:54'),(2,'Blazer Oversized Estruturado','blazer-oversized-estruturado','Blazers','Blazer oversized com lapela bem marcada e ombros estruturados. Uma peça atemporal da coleção Duás que eleva qualquer look minimalista.','70% Lã Fria, 30% Linho com forro de cetim fosco.','Apenas lavagem a seco.',NULL,NULL,890.00,756.50,NULL,NULL,1,1,'2026-09-09 13:59:54'),(3,'Conjunto Calça & Colete Linho Puro','conjunto-calca-colete-linho-puro','Conjuntos','Conjunto confeccionado em linho puro italiano. Colete abotoado ajustado na cintura e calça pantalona de cintura alta com pregas.','100% Linho Puro Rústico.','Lavar à água fria no ciclo delicado. Passar a ferro em temperatura média.',NULL,NULL,1190.00,NULL,NULL,NULL,1,1,'2026-09-09 13:59:54'),(4,'Regata Silk Fluid Off-White','regata-silk-fluid-off-white','Blusas','Regata com alças finas em toque de seda premium e acabamento invisível. Caimento leve e refinado para composições em camadas.','100% Seda Natural Mulberry.','Lavar à mão com sabão neutro para sedas.',NULL,NULL,490.00,NULL,NULL,NULL,0,1,'2026-09-09 13:59:54'),(5,'Calça Alfaiataria Pantalona Noir','calca-alfaiataria-pantalona-noir','Calças','Pantalona em creponado encorpado com caimento pesado e elegante. Cós estruturado com fechamento em gancho embutido.','95% Crepe Viscose, 5% Elastano.','Lavar delicadamente. Secar à sombra na horizontal.',NULL,NULL,680.00,NULL,NULL,NULL,0,1,'2026-09-09 13:59:54'),(6,'Tricot Gola Alta Soft Sand','tricot-gola-alta-soft-sand','Blusas','Tricot ultra macio com trama fina em algodão e cashmere. Gola alta aconchegante e punhos canelados alongados.','85% Algodão Egípcio, 15% Cashmere.','Não pendurar em cabides. Guardar dobrado.',NULL,NULL,620.00,520.00,NULL,NULL,0,1,'2026-09-09 13:59:54'),(7,'Vestido Slip Dress em Seda Chocolate','vestido-slip-dress-seda-chocolate','Vestidos','Vestido Slip Dress de corte enviesado que se molda suavemente ao corpo. Tom chocolate sofisticado exclusivo da temporada.','100% Seda Pura.','Lavagem especializada em lavanderia.',NULL,NULL,950.00,NULL,NULL,NULL,1,1,'2026-09-09 13:59:54'),(8,'Trench Coat Clássico Editorial','trench-coat-classico-editorial','Blazers','Casaco impermeável tipo trench coat com faixa de amarração e fivela encapada. Acabamento interno totalmente forrado em estampa minimalista.','100% Algodão Gabardine de alta gramatura.','Limpeza a seco profissional.',NULL,NULL,1490.00,NULL,NULL,NULL,0,1,'2026-09-09 13:59:54');

