INSERT IGNORE INTO `blog_posts` (`id`, `title`, `slug`, `category`, `read_time`, `excerpt`, `cover_image`, `content`, `content_format`, `is_active`, `published_at`, `published_label`, `created_at`) VALUES (1,'A Poética do Vestir: Diálogo entre Alfaiataria e Conforto por Larissa & Leticia','poetica-do-vestir-alfaiataria-larissa-leticia','Universo Duás','4 min de leitura','Como o design autoral das criadoras busca desmistificar a alfaiataria rígida em favor de cortes fluidos e fibras naturais de presença marcante.','https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=1200&q=80','<p class=\"lead\">Para nós, criar vestuário é um exercício constante de escuta. A alfaiataria não deve aprisionar o corpo, mas sim emoldurar a presença com leveza e precisão.</p><p>Na busca pela simbiose entre estética editorial e usabilidade no cotidiano, desenhamos peças cujas linhas limpas e ombros estruturados coexistem pacificamente com linho rústico e sedas fluidas.</p><h3>Matéria-Prima com Propósito</h3><p>Cada tecido selecionado na Duás passa por um rigoroso teste de toque e movimento. Priorizamos algodões egípcios, linhos italianos e viscose creponada sustentável que oferecem respirabilidade sem abrir mão do caimento impecável.</p><blockquote>\"Criar é traduzir a elegância sem esforço em formas que perduram no armário por gerações.\" — Larissa & Leticia</blockquote>','html',1,'2026-09-05','05 de Setembro, 2026','2026-09-09 13:59:54'),(2,'Guia de Estilo: O Poder das Camadas Neutras no Armário Cápsula','guia-estilo-camadas-neutras-armario-capsula','Estilo & Dicas','6 min de leitura','Descubra como combinar regatas de seda, coletes abotoados e blazers oversized criando um guarda-roupa coeso e sofisticado.','https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=80','<p class=\"lead\">O segredo de um visual impecável muitas vezes reside no contraste harmonioso de texturas e proporções em tons sóbrios.</p><p>Ao sobrepor um colete de linho sobre uma regata de seda fluida e finalizar com um blazer de alfaiataria, você cria dimensão e riqueza visual imediata.</p><h3>As 4 Peças Essenciais</h3><ul><li><strong>O Blazer Oversized:</strong> Estrutura os ombros e equilibra silhuetas justas.</li><li><strong>A Pantalona de Cós Alto:</strong> Alonga e garante liberdade total nos movimentos.</li><li><strong>A Regata de Seda:</strong> Traz luminosidade suave sob casacos.</li><li><strong>O Vestido Slip Dress:</strong> Transita do dia à noite com a troca dos acessórios.</li></ul>','html',1,'2026-08-28','28 de Agosto, 2026','2026-09-09 13:59:54'),(3,'Arquitetura & Moda: A Inspiração Minimalista por Trás das Nossas Formas','arquitetura-moda-inspiracao-minimalista-duas','Inspiração','5 min de leitura','A relação direta entre o brutalismo poético da arquitetura contemporânea e os recortes geométricos da nova coleção da Duás.','https://images.unsplash.com/photo-1445205170230-053b83016050?auto=format&fit=crop&w=1200&q=80','<p class=\"lead\">Linhas puras, volumes calculados e ausência de excessos ornamentais definem tanto os espaços inspiradores quanto nossas roupas.</p><p>Exploramos a tridimensionalidade dos tecidos dobrados, mantendo o foco na pureza dos materiais e na precisão dos acabamentos ocultos.</p>','html',1,'2026-08-15','15 de Agosto, 2026','2026-09-09 13:59:54');

