INSERT IGNORE INTO `blog_posts` (`id`, `title`, `slug`, `category`, `read_time`, `excerpt`, `cover_image`, `content`, `content_format`, `is_active`, `published_at`, `published_label`, `created_at`) VALUES (11,'A Alfaiataria Que Respira','alfaiataria-que-respira','Universo Duás','3 min de leitura','','https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=80','As alfaiatarias mudaram, e o corpo agradece.\n\nDurante anos, vestir uma peça estruturada significou abrir mão do conforto. A gente discorda dessa conta.\n\n## O que mudou nas nossas modelagens\n\n- Ombros com estrutura leve, sem enchimento rígido\n- Cavas mais generosas para o braço se mover\n- Forros em viscose, que respiram\n\n> Conforto não é o oposto de elegância. É o que sustenta ela.\n\nO resultado é uma peça que você veste às 8h e ainda quer estar usando às 22h.','text',1,'2026-09-09',NULL,'2026-09-09 21:02:45');

