INSERT INTO `promotions` (`name`,`code`,`discount_type`,`discount_value`,`min_subtotal`,`starts_at`,`ends_at`,`usage_limit`,`used_count`,`is_active`)
SELECT * FROM (
    SELECT 'Frete no bolso' n, 'DUAS20' c, 'percent' t, 20.00 v, 900.00 m, NULL s, NULL e, NULL l, 0 u, 1 a UNION ALL
    SELECT 'Pré-lançamento verão', 'VERAO26', 'percent', 15.00, 0.00, DATE_ADD(NOW(), INTERVAL 3 DAY), DATE_ADD(NOW(), INTERVAL 30 DAY), NULL, 0, 1 UNION ALL
    SELECT 'Black Friday (encerrada)', 'BF2025', 'percent', 30.00, 0.00, DATE_SUB(NOW(), INTERVAL 40 DAY), DATE_SUB(NOW(), INTERVAL 10 DAY), NULL, 0, 1 UNION ALL
    SELECT 'Primeiras 5 clientes', 'PRIMEIRA', 'fixed', 80.00, 500.00, NULL, NULL, 5, 5, 1
) AS novos
WHERE NOT EXISTS (SELECT 1 FROM `promotions` p WHERE p.`code` = novos.c);

INSERT INTO `free_shipping_rules` (`label`,`min_subtotal`,`starts_at`,`ends_at`,`is_active`)
SELECT 'Campanha de aniversário', 400.00, DATE_ADD(NOW(), INTERVAL 7 DAY), DATE_ADD(NOW(), INTERVAL 21 DAY), 1
WHERE NOT EXISTS (SELECT 1 FROM `free_shipping_rules` WHERE `label` = 'Campanha de aniversário');

